@push('styles')
<style>
    .attendance-page{display:grid;gap:24px}.attendance-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding:22px 24px;border:1px solid var(--line);border-left:4px solid var(--secondary);border-radius:10px;background:#fff}.attendance-head h1{margin:10px 0 6px;font-size:30px;line-height:1.2}.attendance-head p{margin:0;max-width:760px;color:var(--muted);font-size:14px;line-height:1.55}.attendance-head__meta{display:grid;gap:4px;justify-items:end;font-size:13px;color:var(--muted);text-align:right}.attendance-head__meta strong{display:block;color:var(--text);font-size:15px}.attendance-kicker{display:inline-flex;align-items:center;min-height:24px;padding:0 8px;border-radius:4px;background:var(--secondary-soft);color:var(--secondary);font-size:12px;font-weight:700;letter-spacing:.06em}.attendance-overview{display:grid;grid-template-columns:1.2fr .8fr;gap:20px}.attendance-panel{border:1px solid var(--line);border-radius:10px;background:#fff;overflow:hidden}.attendance-panel__head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:18px 20px;border-bottom:1px solid var(--line)}.attendance-panel__head h2{margin:0;font-size:19px}.attendance-panel__head p{margin:5px 0 0;color:var(--muted);font-size:13px}.attendance-detail{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));margin:0}.attendance-detail div{padding:16px 20px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.attendance-detail div:nth-child(2n){border-right:0}.attendance-detail div:nth-last-child(-n+2){border-bottom:0}.attendance-detail span,.attendance-label{display:block;color:var(--muted);font-size:12px;font-weight:700}.attendance-detail strong{display:block;margin-top:6px;font-size:17px}.attendance-action{padding:20px}.attendance-action__status{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px;padding:14px 16px;background:var(--surface-soft);border:1px solid var(--line);border-radius:8px}.attendance-action__status span{color:var(--muted);font-size:13px}.attendance-action__status strong{font-size:15px}.attendance-primary,.attendance-secondary,.attendance-danger{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border:1px solid transparent;border-radius:7px;font:inherit;font-size:14px;font-weight:700;text-decoration:none;cursor:pointer}.attendance-primary{background:var(--secondary);border-color:var(--secondary);color:#fff}.attendance-primary:hover{background:#1d4ed8}.attendance-secondary{background:#fff;border-color:var(--line-strong);color:var(--text)}.attendance-secondary:hover{background:var(--surface-soft)}.attendance-danger{background:var(--danger-soft);border-color:var(--danger-soft);color:var(--danger)}.attendance-danger:hover{background:#fecaca}.attendance-action .attendance-primary{width:100%}.attendance-help{margin:12px 0 0;color:var(--muted);font-size:12px;line-height:1.5}.attendance-note{padding:14px 16px;border-left:3px solid var(--secondary);background:var(--secondary-soft);color:var(--secondary);font-size:13px}.attendance-metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));border:1px solid var(--line);border-radius:10px;overflow:hidden;background:#fff}.attendance-metric{padding:16px 18px;border-right:1px solid var(--line)}.attendance-metric:last-child{border:0}.attendance-metric span{display:block;color:var(--muted);font-size:12px;font-weight:700}.attendance-metric strong{display:block;margin-top:7px;font-size:25px;line-height:1}.attendance-toolbar{display:flex;align-items:end;gap:12px;padding:16px 20px;border-bottom:1px solid var(--line);background:var(--surface-soft)}.attendance-toolbar label{display:grid;gap:6px;min-width:160px;color:var(--muted);font-size:12px;font-weight:700}.attendance-toolbar input,.attendance-toolbar select,.attendance-form input,.attendance-form select,.attendance-form textarea{width:100%;min-height:40px;padding:9px 11px;border:1px solid var(--line-strong);border-radius:7px;background:#fff;color:var(--text);font:inherit;font-size:14px;outline:0}.attendance-toolbar input:focus,.attendance-toolbar select:focus,.attendance-form input:focus,.attendance-form select:focus,.attendance-form textarea:focus{border-color:var(--secondary);box-shadow:0 0 0 3px rgba(36,83,166,.12)}.attendance-table-wrap{overflow-x:auto}.attendance-table{width:100%;min-width:900px;border-collapse:collapse}.attendance-table th{padding:13px 16px;background:var(--surface-soft);border-bottom:1px solid var(--line);color:var(--muted);font-size:12px;font-weight:700;text-align:left;white-space:nowrap}.attendance-table td{padding:15px 16px;border-bottom:1px solid var(--line);font-size:14px;vertical-align:middle}.attendance-table tbody tr:hover{background:#fbfdff}.attendance-table tr:last-child td{border-bottom:0}.attendance-person{display:grid;gap:3px}.attendance-person strong{font-size:14px}.attendance-person span{color:var(--muted);font-size:12px}.attendance-badge{display:inline-flex;align-items:center;justify-content:center;width:max-content;min-height:25px;padding:3px 9px;border-radius:999px;font-size:12px;font-weight:700}.attendance-badge--present{color:#15803d;background:#dcfce7}.attendance-badge--late,.attendance-badge--early_leave{color:#b45309;background:#fef3c7}.attendance-badge--missing_checkout,.attendance-badge--absent{color:#b91c1c;background:#fee2e2}.attendance-badge--working{color:#1d4ed8;background:#dbeafe}.attendance-badge--pending{color:#b45309;background:#fef3c7}.attendance-badge--approved{color:#15803d;background:#dcfce7}.attendance-badge--rejected{color:#b91c1c;background:#fee2e2}.attendance-form{display:grid;gap:16px;padding:20px}.attendance-form__grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.attendance-form label{display:grid;gap:7px;color:var(--text);font-size:13px;font-weight:700}.attendance-form textarea{min-height:100px;resize:vertical}.attendance-form__footer{display:flex;align-items:center;gap:10px;padding-top:4px}.attendance-list{display:grid}.attendance-list__item{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 20px;border-bottom:1px solid var(--line)}.attendance-list__item:last-child{border-bottom:0}.attendance-list__item strong,.attendance-list__item span{display:block}.attendance-list__item span{margin-top:3px;color:var(--muted);font-size:13px}.attendance-empty{padding:28px 20px;text-align:center;color:var(--muted);font-size:14px}.attendance-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:9px;overflow:hidden}.attendance-summary div{padding:15px;background:#fff}.attendance-summary span{display:block;color:var(--muted);font-size:12px;font-weight:700}.attendance-summary strong{display:block;margin-top:6px;font-size:19px}.attendance-actions{display:flex;align-items:center;gap:8px;white-space:nowrap}.attendance-actions form{display:inline}.attendance-inline{display:flex;gap:8px;align-items:center}.attendance-section-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:1000px){.attendance-overview,.attendance-section-grid{grid-template-columns:1fr}.attendance-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.attendance-metric:nth-child(3){border-right:0}.attendance-metric:nth-child(-n+3){border-bottom:1px solid var(--line)}}@media(max-width:680px){.attendance-head{align-items:flex-start;flex-direction:column;padding:18px 16px}.attendance-head__meta{justify-items:start;text-align:left}.attendance-detail,.attendance-form__grid{grid-template-columns:1fr}.attendance-detail div{border-right:0}.attendance-detail div:nth-last-child(2){border-bottom:1px solid var(--line)}.attendance-toolbar{align-items:stretch;flex-direction:column}.attendance-toolbar label{min-width:0}.attendance-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.attendance-metric:nth-child(3){border-right:1px solid var(--line)}.attendance-metric:nth-child(2n){border-right:0}.attendance-metric:nth-child(-n+3){border-bottom:1px solid var(--line)}.attendance-metric:nth-child(4){border-bottom:1px solid var(--line)}.attendance-form__footer,.attendance-actions{align-items:stretch;flex-direction:column}.attendance-actions form,.attendance-actions a{width:100%}.attendance-actions .attendance-primary,.attendance-actions .attendance-secondary,.attendance-actions .attendance-danger{width:100%}}
